'use strict';
let characterBookLimit=60,characterBookReturn=null,characterBookDetail=false;
function renderCharacterCollectionSummary(){const node=document.getElementById('character-collection-summary');const es=KanjiElementCharacters.summary(gameState),ep=document.getElementById('element-summon-progress');if(ep)ep.textContent=`元素文字の発見 ${es.found} / ${es.total} 種類`;if(!node)return;const summary=KanjiCodex.summary(gameState,KANJI_DATABASE,getRealReadings);node.textContent=`入手 ${summary.found.toLocaleString()} / ${summary.total.toLocaleString()}種・シークレット ${summary.secret.found}種`;}
window.openCharacterBook=()=>{characterBookReturn=document.activeElement;characterBookLimit=60;pausePlayerOverlay();document.getElementById('modal-character-book').classList.remove('hidden');renderCharacterBook();document.querySelector('#modal-character-book .editor-panel').scrollTop=0;document.querySelector('#modal-character-book .editor-title button').focus();};
window.restoreCharacterBook=()=>{if(characterBookDetail){characterBookDetail=false;document.getElementById('modal-character-book').classList.remove('hidden');}};
window.closeCharacterBook=()=>{characterBookDetail=false;document.getElementById('modal-character-book').classList.add('hidden');resumePlayerEngine();if(characterBookReturn?.isConnected)characterBookReturn.focus();};
window.renderCharacterBook=reset=>{
 if(reset)characterBookLimit=60;
 renderCodexRewards();const summary=KanjiCodex.summary(gameState,KANJI_DATABASE,getRealReadings),found=new Set(gameState.characterDiscoveries||[]);
 document.getElementById('character-book-total').textContent=`${summary.found.toLocaleString()} / ${summary.total.toLocaleString()}`;
 document.getElementById('character-book-secret').textContent=`シークレット ${summary.secret.found} / ${summary.secret.total}種を発見`;
 const tiers=document.getElementById('character-book-tiers');tiers.replaceChildren();for(const tier of summary.tiers){const row=document.createElement('div');row.className='book-tier';const title=document.createElement('span');title.textContent=`JIS第${tier.jis}水準`;const count=document.createElement('strong');count.textContent=`${tier.found.toLocaleString()} / ${tier.total.toLocaleString()}`;const progress=document.createElement('progress');progress.max=tier.total;progress.value=tier.found;progress.setAttribute('aria-label',`JIS第${tier.jis}水準の収集数`);row.append(title,count,progress);tiers.append(row);}
 const elementSummary=KanjiElementCharacters.summary(gameState),erow=document.createElement('div');erow.className='book-tier';const etitle=document.createElement('span'),ecount=document.createElement('strong'),eprogress=document.createElement('progress');etitle.textContent='元素文字';ecount.textContent=`${elementSummary.found} / ${elementSummary.total}`;eprogress.max=elementSummary.total;eprogress.value=elementSummary.found;eprogress.setAttribute('aria-label','元素文字の収集数');erow.append(etitle,ecount,eprogress);tiers.append(erow);
 const fishSummary=KanjiFishCharacters.summary(gameState),frow=document.createElement('div');frow.className='book-tier';const ftitle=document.createElement('span'),fcount=document.createElement('strong'),fprogress=document.createElement('progress');ftitle.textContent='魚偏の文字';fcount.textContent=`${fishSummary.found} / ${fishSummary.total}`;fprogress.max=fishSummary.total;fprogress.value=fishSummary.found;fprogress.setAttribute('aria-label','魚偏の文字の収集数');frow.append(ftitle,fcount,fprogress);tiers.append(frow);
 const filters={status:document.getElementById('character-book-status').value,jis:document.getElementById('character-book-jis').value,query:document.getElementById('character-book-search').value},items=KanjiCodex.list(gameState,KANJI_DATABASE,getRealReadings,filters),grid=document.getElementById('character-book-grid'),owned=new Map();for(const item of gameState.inventory){if(!owned.has(item.char))owned.set(item.char,[]);owned.get(item.char).push(item);}grid.replaceChildren();
 for(const base of items.slice(0,characterBookLimit)){
  const known=found.has(base.char),secret=isSecretKanji(base),copies=owned.get(base.char)||[],button=document.createElement('button');button.type='button';button.className='book-character';button.dataset.found=String(known);button.dataset.secret=String(secret);if(known||!secret)button.dataset.char=base.char;button.disabled=secret&&!known;
  const glyph=document.createElement('strong');glyph.className='kanji-font';glyph.textContent=secret&&!known?'？':base.char;
  const tier=document.createElement('span');tier.textContent=`${getCharacterTypeLabel(base)}`;
  const state=document.createElement('small');state.textContent=copies.length?`所持 ${copies.length}体`:known?'入手済み':'未入手';
  button.setAttribute('aria-label',secret&&!known?'未発見のシークレット':`${base.char}・${state.textContent}の詳細`);button.append(glyph,tier,state);
  if(secret){const label=document.createElement('small');label.className='book-secret';label.textContent=known?'シークレット':'錬成限定';button.append(label);}
  button.onclick=()=>{const item=copies.slice().sort((a,b)=>b.level-a.level)[0]||{...base,level:1,equippedReadings:getRealReadings(base.char).slice(0,1)};characterBookDetail=true;document.getElementById('modal-character-book').classList.add('hidden');openPieceDetail({...item,equippedReadings:getEquippedReadings(item).slice()});if(!copies.length){const note=document.createElement('p');note.className='book-detail-note';note.textContent=known?'入手記録は残っています。現在は未所持のため、Lv.1・基本ルビで表示しています。':'未入手の文字です。Lv.1・基本ルビで表示しています。';document.getElementById('piece-detail-content').prepend(note);}};
  grid.append(button);
 }
 if(!items.length){const empty=document.createElement('p');empty.className='book-empty';empty.textContent='条件に合う文字がありません。';grid.append(empty);}
 document.getElementById('character-book-count').textContent=`${Math.min(characterBookLimit,items.length).toLocaleString()} / ${items.length.toLocaleString()}種を表示`;
 document.getElementById('btn-character-book-more').hidden=items.length<=characterBookLimit;
};
window.showMoreCharacterBook=()=>{characterBookLimit+=60;renderCharacterBook();};

function renderCodexRewards(){const box=document.getElementById('codex-rewards');box.replaceChildren();for(const m of KanjiGoals.missions.filter(m=>m.id.startsWith('codex-'))){const p=KanjiGoals.progress(gameState,m.id),card=document.createElement('article');card.className='adventure-card';const h=document.createElement('h4');h.textContent=m.name;const text=document.createElement('p');text.textContent=`${Math.min(p.found,p.total).toLocaleString()} / ${p.total.toLocaleString()}種類・${m.coins.toLocaleString()}文`;const honor=KanjiHonors.get(m.frame||m.id);if(honor)text.textContent+='・専用枠「'+honor.name+'」';const button=document.createElement('button');button.className='inventory-action';button.type='button';button.dataset.codexReward=m.id;button.textContent=p.claimed?'受取済み':p.complete?'報酬を受け取る':'収集途中';button.disabled=p.claimed||!p.complete;button.onclick=()=>{try{KanjiGoals.claim(gameState,m.id);saveState();renderCharacterBook();refreshCollectionAdventure();showToast(m.name+'達成！ '+m.coins.toLocaleString()+'文を受け取りました。'+(honor?'専用枠はプロフィールで選べます。':''));}catch{renderCharacterBook();}};card.append(h,text,button);box.append(card);}}
